package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
final class ReferenceSetsDialog {
 static void show(MainActivity owner,java.util.function.Consumer<String> restore){try{JSONObject all=ReferenceSets.read(owner);JSONArray saved=all.getJSONArray("items");LinearLayout box=new LinearLayout(owner);box.setOrientation(1);EditText name=new EditText(owner),query=new EditText(owner);name.setHint("仕事・相談ごとのセット名");query.setHint("メモ・会議・画像の読み取りを検索");box.addView(name);box.addView(query);Button search=new Button(owner);search.setText("参照を検索して選ぶ");box.addView(search);TextView status=new TextView(owner);status.setText("選んだ本文のコピーだけを暗号化して保存します。元の記録を編集・削除しても自動更新しません。写真の画素は含みません。");box.addView(status);LinearLayout results=new LinearLayout(owner);results.setOrientation(1);box.addView(results);JSONArray selected=new JSONArray();Button save=new Button(owner);save.setText("選択した参照をセットに保存");box.addView(save);
 search.setOnClickListener(v->{search.setEnabled(false);String q=query.getText().toString();new Thread(()->{try{JSONObject data=UnifiedRecords.search(owner,q);owner.runOnUiThread(()->{results.removeAllViews();for(int i=0;i<data.optJSONArray("items").length();i++){JSONObject row=data.optJSONArray("items").optJSONObject(i);CheckBox check=new CheckBox(owner);check.setText(UnifiedRecordsDialog.kind(row.optString("type"))+" / "+row.optString("title")+"\n"+row.optString("body").substring(0,Math.min(100,row.optString("body").length())));check.setOnCheckedChangeListener((b,on)->{String key=row.optString("type")+":"+row.optString("id");for(int j=selected.length()-1;j>=0;j--){JSONObject old=selected.optJSONObject(j);if(key.equals(old.optString("type")+":"+old.optString("id")))selected.remove(j);}if(on)selected.put(row);status.setText("選択 "+selected.length()+"件。本文全文を保存します。長い記録は別の短いメモに要点を保存してください。");});results.addView(check);}});}catch(Exception e){owner.runOnUiThread(()->status.setText("検索できません。検索語と保存状態を確認してください"));}finally{owner.runOnUiThread(()->search.setEnabled(true));}},"ReferenceSetSearch").start();});
 save.setOnClickListener(v->{try{ReferenceSets.save(owner,name.getText().toString(),selected,all.optLong("revision"));save.setEnabled(false);status.setText("保存しました。閉じて開き直すと下書きに使えます。送信はしていません。");}catch(Exception e){status.setText(e.getMessage());}});
 for(int i=0;i<saved.length();i++){final int index=i;JSONObject set=saved.getJSONObject(i);Button b=new Button(owner);b.setText(set.getString("name")+" / "+set.getJSONArray("sources").length()+"件");box.addView(b);b.setOnClickListener(v->{try{String draft=ReferenceSets.draft(set);new AlertDialog.Builder(owner).setTitle("保存時点の参照内容").setMessage(draft).setPositiveButton("入力欄へ（送信しない）",(d,w)->restore.accept(draft)).setNeutralButton("比較・管理",(d,w)->new AlertDialog.Builder(owner).setTitle("参照セット").setItems(new String[]{"元の記録の変更を確認","セットを削除"},(menu,choice)->{if(choice==0)ReferenceRefreshDialog.show(owner,index,all.optLong("revision"));else new AlertDialog.Builder(owner).setMessage("この参照セットを削除します。元の記録は保持します。").setPositiveButton("削除",(a,z)->{try{ReferenceSets.remove(owner,index,all.optLong("revision"));b.setEnabled(false);}catch(Exception e){status.setText(e.getMessage());}}).setNegativeButton("戻る",null).show();}).setNegativeButton("戻る",null).show()).setNegativeButton("閉じる",null).show();}catch(Exception e){status.setText("参照内容を開けません");}});}
 ScrollView scroll=new ScrollView(owner);scroll.addView(box);new AlertDialog.Builder(owner).setTitle("仕事・相談ごとの参照セット").setView(scroll).setPositiveButton("閉じる",null).show();
 }catch(Exception e){new AlertDialog.Builder(owner).setMessage("参照セットを開けません。保存内容は保持しています").setPositiveButton("閉じる",null).show();}}
 private ReferenceSetsDialog(){}
}
